create or replace function public.api_claim_conversion() returns public.conversion_jobs language plpgsql set search_path='' as $$declare j public.conversion_jobs;begin update public.conversion_jobs set status='failed',error='转换运行器超时，请重试',lease_id=null,lease_until=null where status='running' and lease_until<now();select * into j from public.conversion_jobs where status='queued' and expires_at>now() order by created_at for update skip locked limit 1;if j.id is null then return null;end if;update public.conversion_jobs set status='running',lease_id=gen_random_uuid(),lease_until=now()+interval '15 minutes',output_path=user_id::text||'/converted/'||id::text||'.'||case when target='png' then 'zip' else target end where id=j.id returning * into j;return j;end$$;
